import { PrismaClient } from '@prisma/client';

export async function issueInvoice(db: PrismaClient, orderId: string) {
  const order = await db.order.findUniqueOrThrow({ where: { id: orderId } });
  if (order.status !== 'paid') throw new Error('order not paid');
  return db.invoice.create({ data: { orderId, total: order.total } });
}

export interface Clock { now(): Date }
export interface UserRepo { findById(id: string): Promise<{ id: string; trialEndsAt: Date } | null> }

export class TrialService {
  constructor(private readonly users: UserRepo, private readonly clock: Clock) {}

  async isExpired(userId: string): Promise<boolean> {
    const user = await this.users.findById(userId);
    if (!user) throw new Error('user not found');
    return this.clock.now() > user.trialEndsAt;
  }
}

