export interface SmsSender { send(to: string, text: string): Promise<void> }
export class SmsRateLimited extends Error {}

// Adapter: our interface -> vendor HTTP API
export class EskizSmsSender implements SmsSender {
  constructor(private readonly token: string, private readonly from: string) {}
  async send(to: string, text: string) {
    const res = await fetch('https://notify.eskiz.uz/api/message/sms/send', {
      method: 'POST',
      headers: { Authorization: `Bearer ${this.token}` },
      body: new URLSearchParams({ mobile_phone: to, message: text, from: this.from }),
      signal: AbortSignal.timeout(5_000),
    });
    if (res.status === 429) throw new SmsRateLimited();
    if (!res.ok) throw new Error(`eskiz ${res.status}: ${await res.text()}`);
  }
}

// Decorator: same interface, adds retry for rate limits only
export function withRetry(inner: SmsSender, attempts = 3): SmsSender {
  return {
    async send(to, text) {
      for (let i = 1; ; i++) {
        try { return await inner.send(to, text); }
        catch (e) {
          if (!(e instanceof SmsRateLimited) || i >= attempts) throw e;
          await new Promise(r => setTimeout(r, 2 ** i * 250));
        }
      }
    },
  };
}
