interface PriceApi { price(sku: string): Promise<number> }
const cache = new Map<string, { value: number; at: number }>();

export function withCache(inner: PriceApi, ttlMs = 60_000): PriceApi {
  return {
    async price(sku) {
      const hit = cache.get(sku);
      if (hit && Date.now() - hit.at < ttlMs) return hit.value;
      try {
        const value = await inner.price(sku);
        cache.set(sku, { value, at: Date.now() });
        return value;
      } catch {
        return hit?.value ?? 0;
      }
    },
  };
}

