export interface Orders { save(o: Order): Promise<void> }
export interface Payments { charge(orderId: string, amount: bigint, idemKey: string): Promise<'ok' | 'declined'> }
export type Order = { id: string; items: { sku: string; qty: number; price: bigint }[]; status: 'new' | 'paid' | 'declined' };

// core/placeOrder.ts — no Express, no Prisma, no Stripe
export async function placeOrder(cmd: { id: string; items: Order['items'] }, deps: { orders: Orders; payments: Payments }) {
  if (cmd.items.length === 0) throw new Error('empty cart');
  const total = cmd.items.reduce((s, i) => s + i.price * BigInt(i.qty), 0n);
  const order: Order = { ...cmd, status: 'new' };
  await deps.orders.save(order);
  const result = await deps.payments.charge(order.id, total, `order-${order.id}`);
  order.status = result === 'ok' ? 'paid' : 'declined';
  await deps.orders.save(order);
  return order;
}

