export async function cancelBooking(req: Request<{ id: string }>, repo: BookingRepo, now: Date) {
  const b = await repo.byId(req.params.id);
  if (!b) throw new NotFound('booking');
  if (b.startsAt.getTime() - now.getTime() < 2 * 3600_000) throw new TooLate();
  b.status = 'cancelled';
  await repo.save(b);
}

