export class Money {
  private constructor(readonly minor: bigint, readonly currency: 'UZS' | 'USD') {}
  static of(minor: bigint, currency: 'UZS' | 'USD') { return new Money(minor, currency); }
  add(o: Money) {
    if (o.currency !== this.currency) throw new Error('currency mismatch');
    return new Money(this.minor + o.minor, this.currency);
  }
}

type Line = { sku: string; qty: number; unit: Money };

export class Order {               // aggregate root
  private lines: Line[] = [];
  private status: 'draft' | 'placed' = 'draft';
  readonly events: { type: 'OrderPlaced'; orderId: string }[] = [];
  constructor(readonly id: string, private readonly currency: 'UZS' | 'USD') {}

  addLine(sku: string, qty: number, unit: Money) {
    if (this.status !== 'draft') throw new Error('order already placed');
    if (qty <= 0 || qty > 100) throw new Error('qty must be 1..100');
    this.lines.push({ sku, qty, unit });
  }

  total() {
    return this.lines.reduce((s, l) => s.add(Money.of(l.unit.minor * BigInt(l.qty), l.unit.currency)), Money.of(0n, this.currency));
  }

  place() {
    if (this.lines.length === 0) throw new Error('empty order');
    this.status = 'placed';
    this.events.push({ type: 'OrderPlaced', orderId: this.id });
  }
}

export class Order {
  status: 'draft' | 'placed' = 'draft';
  lines: Line[] = [];
  addLine(l: Line) {
    if (this.status !== 'draft') throw new Error('order already placed');
    if (l.qty < 1 || l.qty > 100) throw new Error('qty must be 1..100');
    this.lines.push(l);
  }
}

