// 2. abstraction in front of old code; new code behind a flag
export interface ShippingCalculator { cost(i: ShipInput): number }

export function makeShipping(flags: { useNew: boolean; shadow: boolean }, log: (m: object) => void): ShippingCalculator {
  return {
    cost(i) {
      if (flags.useNew) return newShippingCost(i);
      const oldCost = legacyShippingCost(i);
      if (flags.shadow) {
        const n = newShippingCost(i);
        if (n !== oldCost) log({ msg: 'shipping_mismatch', input: i, old: oldCost, new: n });
      }
      return oldCost; // users still get the old answer
    },
  };
}

// before
function totalBefore(lines: { price: number; qty: number }[]) {
  let t = 0;
  for (const l of lines) t += Math.round(l.price * l.qty * 1.12);
  return t;
}

// after
function totalAfter(lines: { price: number; qty: number }[]) {
  const net = lines.reduce((s, l) => s + l.price * l.qty, 0);
  return Math.round(net * 1.12);
}

